// ============================================================================
// M_PHY_apb: APB4 register wrapper around M_PHY_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/M_PHY.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/M_PHY.md
// ============================================================================
module M_PHY_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic tx_dif_p,
  output logic tx_dif_n,
  input logic rx_dif_p,
  input logic rx_dif_n
);
  localparam logic [31:0] ID_VALUE = 32'h4D500200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_irq;
  logic          c_irq_clear;
  logic          c_gear;
  logic          c_hibern8_req;
  logic          c_wake_req;
  logic          c_hibern8;
  logic [7:0]    c_tx_data;
  logic          c_tx_k;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic          c_rx_locked;
  logic          c_rx_hibern;
  logic [7:0]    c_rx_data;
  logic          c_rx_k;
  logic          c_rx_valid;
  M_PHY_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .irq(c_irq),
    .irq_clear(c_irq_clear),
    .gear(c_gear),
    .hibern8_req(c_hibern8_req),
    .wake_req(c_wake_req),
    .hibern8(c_hibern8),
    .tx_data(c_tx_data),
    .tx_k(c_tx_k),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_dif_p(tx_dif_p),
    .tx_dif_n(tx_dif_n),
    .rx_dif_p(rx_dif_p),
    .rx_dif_n(rx_dif_n),
    .rx_locked(c_rx_locked),
    .rx_hibern(c_rx_hibern),
    .rx_data(c_rx_data),
    .rx_k(c_rx_k),
    .rx_valid(c_rx_valid)
  );

  // ---------------- registers ----------------
  logic [4:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [2:0] p_CMD;   // 12'h014 CMD (pulses)
  logic [0:0] r_CFG;   // 12'h018 CFG
  logic [8:0] h_TX;   // 12'h01C TX holding register
  logic [8:0] h_RX;   // 12'h020 RX holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      p_CMD <= '0;
      r_CFG <= 1'h0;
      h_TX <= '0;
      h_RX <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[4:0] & wmask[4:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      p_CMD <= (wr && hit[5]) ? PWDATA[2:0] & wmask[2:0] : '0;
      if (wr && hit[6]) r_CFG <= (r_CFG & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[7] && !full_TX) h_TX <= (h_TX & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[7] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[8]))) begin
        h_RX[7:0] <= c_rx_data[7:0];
        h_RX[8:8] <= c_rx_k;
        avail_RX <= 1'b1;
      end else if (rd && hit[8]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_hibern8_req = p_CMD[0:0];
  assign c_wake_req = p_CMD[1:1];
  assign c_irq_clear = p_CMD[2:2];
  assign c_gear = r_CFG;
  assign c_tx_data[7:0] = h_TX[7:0];
  assign c_tx_k = h_TX[8:8];
  assign c_tx_valid = full_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
    irq_set[1] = full_TX & c_tx_ready;
    irq_set[2] = wr & (hit[7]) & full_TX;
    irq_set[3] = c_rx_valid & (~avail_RX | (rd & hit[8]));
    irq_set[4] = c_rx_valid & avail_RX & ~(rd & hit[8]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd6: apb_rdata = 32'(r_CFG);
      10'd7: apb_rdata = 32'(h_TX);
      10'd8: apb_rdata = 32'(h_RX);
      10'd9: apb_rdata = 32'({c_rx_hibern, c_rx_locked, c_hibern8});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
